SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[ViewLastCont] AS SELECT * FROM (SELECT dedicati.iddedicato AS MYID, 'Dedicato' AS Tipologia, dedicati.identificativo, dedicati.Nome, dedicati.Matricola,PartipologiaMonopoli.DescrizioneTM,concessionari.nomeconcessionario, move.contatore1, move.contatore2, move.contatore3, move.contatore4,locali.nome as NomeLocale, ditte.nome as Associato, (SELECT Max(data) FROM Incassi WHERE Incassi.codiceoggetto = Move.Dedicato AND Incassi.TipoOggetto = 2) AS DataIncasso   FROM  ((((move INNER JOIN dedicati ON move.Dedicato = dedicati.IdDedicato) left join partipologiamonopoli on dedicati.ParTipologiaMonopoli = Partipologiamonopoli.idpartm)left join locali on locali.idlocale = move.locale)left join concessionari on concessionari.idconcessionario=dedicati.idconcessionario)left join ditte on ditte.idagente=dedicati.agente   WHERE dedicati.DataFine IS NULL and dedicati.dismissione<>-1 UNION SELECT dedicati.iddedicato AS MYID, 'Dedicato' AS Tipologia,  dedicati.identificativo as Identificativo, dedicati.nome, dedicati.matricola,PartipologiaMonopoli.DescrizioneTM,concessionari.nomeconcessionario, relcontatori.contatore1,relcontatori.contatore2, relcontatori.contatore3, relcontatori.contatore4, 'Magazzino' as NomeLocale, ditte.nome as Associato, (SELECT Max(data) FROM Incassi WHERE Incassi.codiceoggetto = dedicati.IdDedicato AND Incassi.TipoOggetto = 2 ) AS DataIncasso  FROM (((dedicati LEFT JOIN relcontatori ON relcontatori.id = dedicati.Iddedicato) left join partipologiamonopoli on dedicati.ParTipologiaMonopoli = Partipologiamonopoli.idpartm)left join concessionari on concessionari.idconcessionario=dedicati.idconcessionario)left join ditte on ditte.idagente=dedicati.agente  WHERE relcontatori.tipo =2 AND dedicati.iddedicato NOT IN (SELECT Move.dedicato FROM Move WHERE move.dedicato=dedicati.iddedicato) AND dedicati.DataFine IS NULL and dedicati.dismissione<>-1) as pippo WHERE 1=1
GO
